import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

function Register() {
  const [nom, setNom] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [classId, setClassId] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/pages/register', {
        nom, email, password, role, class_id: classId || null
      });
      alert('Compte créé avec succès !');
      navigate('/');
    } catch (err) {
      console.error(err);
      alert('Erreur lors de l\'inscription');
    }
  };

  return (
    <div>
      <h2>Inscription</h2>
      <form onSubmit={handleSubmit}>
        <input placeholder="Nom" value={nom} onChange={e => setNom(e.target.value)} required />
        <input type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} required />
        <input type="password" placeholder="Mot de passe" value={password} onChange={e => setPassword(e.target.value)} required />
        <select value={role} onChange={e => setRole(e.target.value)}>
          <option value="student">Étudiant</option>
          <option value="prof">Professeur</option>
        </select>
        {role === 'student' && <input placeholder="Classe ID" value={classId} onChange={e => setClassId(e.target.value)} />}
        <button type="submit">S'inscrire</button>
      </form>
    </div>
  );
}

export default Register;
